  }, [user.id]);

  const loadLinks = () => {
    const userLinks = getLinksByUser(user.id);
    setLinks(userLinks.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()));
  };

  const handleDelete = (id: string) => {
    if (window.confirm("Bạn có chắc chắn muốn xóa link này?")) {
      deleteLink(id);
      loadLinks();
    }
  };

  const handleSimulateVisit = (id: string, url: string) => {
    incrementClick(id);
    loadLinks(); // Refresh stats
    window.open(url, '_blank');
  };

  const filteredLinks = links.filter(link => 
    link.originalUrl.toLowerCase().includes(searchTerm.toLowerCase()) || 
    link.slug.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Prepare data for chart (Top 5 performed links)
  const chartData = links
    .map(l => ({ name: l.slug, clicks: l.clicks }))
