      if (guestLinkId) {
        const link = getLinkById(guestLinkId);
        if (link) {
          setLinks([link]);
          setSelectedLink(link);
        } else {
          // Link not found (maybe expired and cleaned up)
          localStorage.removeItem('guest_link_id');
          setLinks([]);
        }
      }
    }
  };

  const handleDelete = (id: string) => {
    if (isGuest) {
      if (window.confirm("Bạn có chắc muốn hủy link này? Link sẽ bị xóa vĩnh viễn.")) {
        deleteLink(id);
        localStorage.removeItem('guest_link_id');
        loadLinks();
        setSelectedLink(null);
      }
    } else {
      if (window.confirm("CẢNH BÁO: Bạn có chắc chắn muốn xóa link này? Hành động này không thể hoàn tác.")) {
        deleteLink(id);
        loadLinks();
        if (selectedLink?.id === id) setSelectedLink(null);
      }
    }
  };

  const handleSimulateVisit = (slug: string) => {
    // Open the local hash URL (e.g. /#/slug) so it goes through RedirectHandler
    const url = `${window.location.origin}/#/${slug}`;
    window.open(url, '_blank');
    // We reload stats after a short delay to allow the redirect handler to process the click
    setTimeout(() => loadLinks(), 1000);
  };

  const handleUpdateExpiry = (linkId: string) => {
    if (!newExpiryDate) {
      // Clear expiry
      updateLinkExpiry(linkId, null);
    } else {
      updateLinkExpiry(linkId, new Date(newExpiryDate).toISOString());
    }
    setEditingExpiry(null);
    loadLinks();
  };

  const filteredLinks = links.filter(link => 
    link.originalUrl.toLowerCase().includes(searchTerm.toLowerCase()) || 
    link.slug.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Filter Chart Data based on date range
  const getChartData = (link: ShortLink): DailyStat[] => {
    if (!link.history) return [];
    let data = [...link.history];

    if (dateFilter.start) {
      data = data.filter(d => d.date >= dateFilter.start);
    }
    if (dateFilter.end) {
      data = data.filter(d => d.date <= dateFilter.end);
    }

    // Sort by date just in case
    return data.sort((a, b) => a.date.localeCompare(b.date));
  };

  const isExpired = (dateStr?: string | null) => {
    if (!dateStr) return false;
    return new Date(dateStr) < new Date();
  };

  // If guest has no links, show empty state or redirect
  if (isGuest && links.length === 0) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-20 text-center">
         <h2 className="text-xl font-bold text-gray-900">Không tìm thấy link khách</h2>
         <p className="mt-2 text-gray-600">Phiên làm việc của bạn đã hết hạn hoặc bạn chưa tạo link nào.</p>
         <Link to="/" className="mt-4 inline-block text-indigo-600 font-medium">Tạo link mới &rarr;</Link>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-6">
        <h1 className="text-2xl font-bold text-gray-900">
          {isGuest ? 'Quản lý Link Khách (Guest)' : 'Thống kê & Quản lý Link'}
        </h1>
        {isGuest && (
          <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 mt-4 md:mt-0 max-w-lg">
            <div className="flex">
              <div className="ml-3">
                <p className="text-sm text-yellow-700">
                  Đây là phiên khách. Link này sẽ tự động hết hạn và bị xóa sau 24 giờ kể từ khi tạo.
                </p>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Detail & Chart Section */}
      {selectedLink && (
        <div className="bg-white shadow rounded-lg p-6 mb-8 border border-gray-100">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6">
            <div>
              <h2 className="text-lg font-medium text-gray-900 flex items-center gap-2">
                Biểu đồ lượt click: <span className="text-indigo-600">/{selectedLink.slug}</span>
                {isExpired(selectedLink.expiresAt) && <span className="px-2 py-0.5 rounded text-xs bg-red-100 text-red-800">Đã hết hạn</span>}
              </h2>
              <p className="text-sm text-gray-500 mt-1 truncate max-w-md">{selectedLink.originalUrl}</p>
            </div>

            {/* Date Filter */}
            <div className="flex flex-wrap items-center gap-2 mt-4 sm:mt-0">
               <div className="flex items-center gap-1">
                 <label className="text-xs text-gray-500">Từ:</label>
                 <input 
                   type="date" 
                   className="text-sm border border-gray-300 rounded px-2 py-1"
                   value={dateFilter.start}
                   onChange={e => setDateFilter({...dateFilter, start: e.target.value})}
                 />
               </div>
               <div className="flex items-center gap-1">
                 <label className="text-xs text-gray-500">Đến:</label>
                 <input 
                   type="date" 
                   className="text-sm border border-gray-300 rounded px-2 py-1"
                   value={dateFilter.end}
                   onChange={e => setDateFilter({...dateFilter, end: e.target.value})}
                 />
               </div>
               <button 
                  onClick={() => setDateFilter({ start: '', end: '' })}
                  className="text-xs text-indigo-600 hover:text-indigo-800"
                >
                  Xóa lọc
               </button>
            </div>
          </div>

          <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={getChartData(selectedLink)}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E5E7EB" />
                <XAxis dataKey="date" tick={{fontSize: 12}} stroke="#9CA3AF" />
                <YAxis tick={{fontSize: 12}} stroke="#9CA3AF" />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
                />
                <Line type="monotone" dataKey="count" stroke="#4F46E5" strokeWidth={3} activeDot={{ r: 8 }} name="Lượt click" />
              </LineChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-4 text-center text-xs text-gray-400">
             Hiển thị số liệu theo ngày
          </div>
        </div>
      )}

      {/* Link Table */}
      <div className="bg-white shadow rounded-lg overflow-hidden">
        <div className="px-4 py-5 border-b border-gray-200 sm:px-6 flex flex-col sm:flex-row justify-between items-center gap-4">
          <h3 className="text-lg leading-6 font-medium text-gray-900">Danh sách Link</h3>
          {!isGuest && (
            <input 
              type="text" 
              placeholder="Tìm kiếm link..." 
              className="border border-gray-300 rounded-md px-3 py-1.5 text-sm focus:ring-indigo-500 focus:border-indigo-500 w-full sm:w-64"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          )}
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Link rút gọn</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">URL Gốc</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Trạng thái / Hết hạn</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Clicks</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Thao tác</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {filteredLinks.length > 0 ? filteredLinks.map((link) => {
                const expired = isExpired(link.expiresAt);
                return (
                <tr key={link.id} className={`hover:bg-gray-50 cursor-pointer ${selectedLink?.id === link.id ? 'bg-indigo-50' : ''}`} onClick={() => setSelectedLink(link)}>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className="text-indigo-600 font-medium">shrt.ai/{link.slug}</span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="text-sm text-gray-900 truncate max-w-xs" title={link.originalUrl}>{link.originalUrl}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm" onClick={e => e.stopPropagation()}>
                    {editingExpiry === link.id ? (
                      <div className="flex items-center gap-1">
                        <input 
                          type="datetime-local" 
                          className="text-xs border rounded p-1"
                          defaultValue={link.expiresAt ? new Date(link.expiresAt).toISOString().slice(0, 16) : ''}
                          onChange={(e) => setNewExpiryDate(e.target.value)}
                        />
                        <button onClick={() => handleUpdateExpiry(link.id)} className="text-green-600 text-xs font-bold">Lưu</button>
                        <button onClick={() => setEditingExpiry(null)} className="text-gray-500 text-xs">Hủy</button>
                      </div>
                    ) : (
                      <div className="flex items-center gap-2">
                        <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${expired ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'}`}>
                          {expired ? 'Hết hạn' : 'Hoạt động'}
                        </span>
                        <div className="text-xs text-gray-500">
                           {link.expiresAt ? new Date(link.expiresAt).toLocaleDateString() : 'Vô thời hạn'}
                        </div>
                        <button 
                          onClick={() => {
                            setEditingExpiry(link.id);
                            setNewExpiryDate(link.expiresAt || '');
                          }}
                          className="text-gray-400 hover:text-indigo-600"
                          title="Chỉnh sửa ngày hết hạn"
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
                          </svg>
                        </button>
                      </div>
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {link.clicks}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium space-x-2" onClick={e => e.stopPropagation()}>
                    <button 
                      onClick={() => handleSimulateVisit(link.slug)}
                      className="text-indigo-600 hover:text-indigo-900 bg-indigo-50 px-2 py-1 rounded"
                    >
                      Visit
                    </button>
                    <button 
                      onClick={() => handleDelete(link.id)}
                      className="text-red-600 hover:text-red-900 bg-red-50 px-2 py-1 rounded"
                    >
                      Xóa
                    </button>
                  </td>
                </tr>
              )}) : (
                <tr>
                  <td colSpan={5} className="px-6 py-10 text-center text-gray-500">
                    Bạn chưa có link nào. Hãy tạo link mới!
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useEffect, useState } from 'react';
import { User, ShortLink, UserRole } from '../types';
import { getAllUsers, getAllLinks, deleteUser, deleteLink, updateUserRole } from '../services/mockBackend';

interface AdminProps {
  currentUser: User;
}

const Admin: React.FC<AdminProps> = ({ currentUser }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [links, setLinks] = useState<ShortLink[]>([]);
  const [activeTab, setActiveTab] = useState<'users' | 'links'>('users');

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setUsers(getAllUsers());
    setLinks(getAllLinks());
  };

  const handleDeleteUser = (id: string) => {
    if (id === currentUser.id) {
      alert("Bạn không thể xóa chính mình.");
      return;
    }
    if (window.confirm("CẢNH BÁO: Xóa người dùng sẽ xóa tất cả link của họ. Tiếp tục?")) {
      deleteUser(id);
      refreshData();
    }
  };

  const handleRoleChange = (user: User) => {
    if (user.id === currentUser.id) {
        alert("Bạn không thể tự thay đổi quyền của chính mình.");
        return;
    }

    const newRole = user.role === UserRole.ADMIN ? UserRole.USER : UserRole.ADMIN;
