  if (!localStorage.getItem(USERS_KEY)) {
    const adminUser: User = {
      id: 'admin-1',
      email: 'admin@shortai.com',
      name: 'Quản trị viên',
      role: UserRole.ADMIN,
      password: 'admin', 
      createdAt: new Date().toISOString()
    };
    const demoUser: User = {
