// --- Auth Services (User DB) ---

export const login = async (email: string, password: string): Promise<User> => {
  await new Promise(resolve => setTimeout(resolve, 500));

  const users: User[] = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
  const user = users.find(u => u.email === email && u.password === password);

  if (!user) throw new Error("Email hoặc mật khẩu không đúng.");

  const { password: _, ...userWithoutPass } = user;
  localStorage.setItem(SESSION_KEY, JSON.stringify(userWithoutPass));
  return userWithoutPass;
};

export const register = async (email: string, password: string, name: string): Promise<User> => {
  await new Promise(resolve => setTimeout(resolve, 500));

  const users: User[] = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
  if (users.find(u => u.email === email)) throw new Error("Email đã tồn tại.");

  const newUser: User = {
    id: `user-${Date.now()}`,
    email,
    password,
    name,
    role: UserRole.USER,
    createdAt: new Date().toISOString()
  };

  users.push(newUser);
  localStorage.setItem(USERS_KEY, JSON.stringify(users));

  const { password: _, ...userWithoutPass } = newUser;
  localStorage.setItem(SESSION_KEY, JSON.stringify(userWithoutPass));
  return userWithoutPass;
};

export const logout = () => {
  localStorage.removeItem(SESSION_KEY);
};

export const getCurrentUser = (): User | null => {
  const stored = localStorage.getItem(SESSION_KEY);
  return stored ? JSON.parse(stored) : null;
};

export const recoverPassword = async (email: string): Promise<void> => {
  await new Promise(resolve => setTimeout(resolve, 800));
  const users: User[] = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
  const user = users.find(u => u.email === email);
  if (!user) throw new Error("Không tìm thấy email trong hệ thống.");
};

export const updateUserRole = (userId: string, newRole: UserRole) => {
  const users: User[] = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
  const index = users.findIndex(u => u.id === userId);
  if (index !== -1) {
    users[index].role = newRole;
    localStorage.setItem(USERS_KEY, JSON.stringify(users));
  }
};

export const getAllUsers = (): User[] => {
  const users = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
  // Remove passwords
  return users.map((u: User) => {
    const { password, ...rest } = u;
    return rest;
  });
};

export const deleteUser = (userId: string) => {
  let users: User[] = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
  users = users.filter(u => u.id !== userId);
  localStorage.setItem(USERS_KEY, JSON.stringify(users));

  // Clean up user's links
  let links = getAllLinks();
  links = links.filter(l => l.creatorId !== userId);
  localStorage.setItem(LINKS_KEY, JSON.stringify(links));
};

// --- Link Services (Link DB) ---

export const getAllLinks = (): ShortLink[] => {
  // Filter out expired guest links (simple garbage collection on read)
  let links: ShortLink[] = JSON.parse(localStorage.getItem(LINKS_KEY) || '[]');
  // Optional: Clean up really old expired guest links automatically
  return links;
};

export const getLinksByUser = (userId: string): ShortLink[] => {
  const all = getAllLinks();
  return all.filter(l => l.creatorId === userId);
};

export const getLinkById = (linkId: string): ShortLink | undefined => {
  const all = getAllLinks();
  return all.find(l => l.id === linkId);
}

export const getLinkBySlug = (slug: string): ShortLink | undefined => {
  const all = getAllLinks();
  return all.find(l => l.slug === slug);
}

export const createShortLink = async (originalUrl: string, slug: string, creatorId: string = 'guest', expiresAt?: string): Promise<ShortLink> => {
  // Simulate delay only for single create to feel real
  if (creatorId !== 'bulk') {
    await new Promise(resolve => setTimeout(resolve, 300));
  }
  const links = getAllLinks();

  if (links.some(l => l.slug === slug)) {
    throw new Error(`Slug '${slug}' đã được sử dụng.`);
  }

  // Handle Guest Constraints
  if (creatorId === 'guest') {
    // Expiry is hardcoded to 24h for guests
    const tomorrow = new Date();
    tomorrow.setHours(tomorrow.getHours() + 24);
    expiresAt = tomorrow.toISOString();
  }

  const newLink: ShortLink = {
    id: `link-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
    originalUrl,
    slug,
    creatorId: creatorId === 'bulk' ? 'guest' : creatorId, // Handle bulk edge case if needed, but usually we pass real ID
    clicks: 0,
    createdAt: new Date().toISOString(),
    expiresAt: expiresAt || null,
    history: []
  };

  links.push(newLink);
  localStorage.setItem(LINKS_KEY, JSON.stringify(links));
  return newLink;
};

export const bulkCreateShortLinks = async (
  items: { url: string; slug?: string }[],
  creatorId: string
): Promise<{ success: number; errors: string[] }> => {
  await new Promise(resolve => setTimeout(resolve, 1000)); // processing delay
  const errors: string[] = [];
  let successCount = 0;

  for (const item of items) {
    try {
      if (!item.url) continue;
      // Generate slug if missing
      const slug = item.slug || Math.random().toString(36).substring(2, 8);
      await createShortLink(item.url, slug, creatorId);
      successCount++;
    } catch (e: any) {
      errors.push(`Lỗi dòng URL "${item.url}": ${e.message}`);
    }
  }

  return { success: successCount, errors };
};


export const updateLinkExpiry = (linkId: string, expiresAt: string | null) => {
  const links = getAllLinks();
  const index = links.findIndex(l => l.id === linkId);
  if (index !== -1) {
    links[index].expiresAt = expiresAt;
    localStorage.setItem(LINKS_KEY, JSON.stringify(links));
  }
}

export const updateLink = (linkId: string, newSlug: string, newOriginalUrl: string) => {
  const links = getAllLinks();
  const index = links.findIndex(l => l.id === linkId);
  if (index === -1) {
    throw new Error("Không tìm thấy liên kết.");
  }

  // Check collision if slug changed
  if (links[index].slug !== newSlug) {
      if (links.some(l => l.slug === newSlug)) {
          throw new Error(`Slug '${newSlug}' đã tồn tại.`);
      }
  }

  links[index].slug = newSlug;
  links[index].originalUrl = newOriginalUrl;
  localStorage.setItem(LINKS_KEY, JSON.stringify(links));
};

export const deleteLink = (linkId: string) => {
  const links = getAllLinks();
  const newLinks = links.filter(l => l.id !== linkId);
  localStorage.setItem(LINKS_KEY, JSON.stringify(newLinks));
};

export const incrementClick = (linkId: string) => {
  const links = getAllLinks();
  const linkIndex = links.findIndex(l => l.id === linkId);

  if (linkIndex !== -1) {
    const link = links[linkIndex];

    // Check expiry
    if (link.expiresAt && new Date(link.expiresAt) < new Date()) {
       // Expired link, do not increment (in real app, would return 404 or expired page)
       return;
    }

    link.clicks += 1;
    link.lastClickedAt = new Date().toISOString();

    // Update History
    const today = new Date().toISOString().split('T')[0];
    if (!link.history) link.history = [];

    const todayStatIndex = link.history.findIndex(h => h.date === today);
    if (todayStatIndex >= 0) {
      link.history[todayStatIndex].count += 1;
    } else {
      link.history.push({ date: today, count: 1 });
    }

    localStorage.setItem(LINKS_KEY, JSON.stringify(links));
  }
};

// --- Language Services (Language DB) ---

export const getLanguageSettings = (): { currentLang: string, available: string[] } => {
    return JSON.parse(localStorage.getItem(LANG_KEY) || '{"currentLang":"vi","available":["vi"]}');
};

export const setLanguage = (lang: string) => {
    const settings = getLanguageSettings();
    settings.currentLang = lang;
    localStorage.setItem(LANG_KEY, JSON.stringify(settings));
};

import React, { useEffect, useState } from 'react';
import { User, ShortLink, UserRole } from '../types';
import { getAllUsers, getAllLinks, deleteUser, deleteLink, updateUserRole, updateLink } from '../services/mockBackend';

interface AdminProps {
  currentUser: User;
}

const USERS_PER_PAGE = 10;
const LINKS_PER_PAGE = 20;

const Admin: React.FC<AdminProps> = ({ currentUser }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [links, setLinks] = useState<ShortLink[]>([]);
  const [activeTab, setActiveTab] = useState<'users' | 'links'>('users');

  // Search State
  const [linkSearchTerm, setLinkSearchTerm] = useState('');

  // Pagination State
  const [userPage, setUserPage] = useState(1);
  const [linkPage, setLinkPage] = useState(1);

  // Edit State
  const [editingLinkId, setEditingLinkId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState({ slug: '', originalUrl: '' });

  useEffect(() => {
    refreshData();
  }, []);

  // Reset link page when search changes
  useEffect(() => {
    setLinkPage(1);
  }, [linkSearchTerm]);

  const refreshData = () => {
    setUsers(getAllUsers());
    setLinks(getAllLinks());
  };

  // --- User Logic ---
  const handleDeleteUser = (id: string) => {
    if (id === currentUser.id) {
      alert("Bạn không thể xóa chính mình.");
      return;
    }
    if (window.confirm("CẢNH BÁO: Xóa người dùng sẽ xóa tất cả link của họ. Tiếp tục?")) {
      deleteUser(id);
      refreshData();
    }
  };

  const handleRoleChange = (user: User) => {
    if (user.id === currentUser.id) {
        alert("Bạn không thể tự thay đổi quyền của chính mình.");
        return;
    }

    const newRole = user.role === UserRole.ADMIN ? UserRole.USER : UserRole.ADMIN;
    const confirmMsg = `Bạn có chắc chắn muốn thay đổi quyền của "${user.name}" từ ${user.role} thành ${newRole} không?`;

    if (window.confirm(confirmMsg)) {
        updateUserRole(user.id, newRole);
        refreshData();
    }
  };

  // --- Link Logic ---
  const handleDeleteLink = (id: string) => {
    if (window.confirm("CẢNH BÁO: Bạn có chắc chắn muốn xóa link này khỏi hệ thống không?")) {
      deleteLink(id);
      refreshData();
    }
  };

  const handleSimulateVisit = (slug: string) => {
    const url = `${window.location.origin}/#/${slug}`;
    window.open(url, '_blank');
  };

  const startEditing = (link: ShortLink) => {
    setEditingLinkId(link.id);
    setEditForm({ slug: link.slug, originalUrl: link.originalUrl });
  };

  const cancelEditing = () => {
    setEditingLinkId(null);
    setEditForm({ slug: '', originalUrl: '' });
  };

  const saveEditing = (linkId: string) => {
    if (!window.confirm("Bạn có chắc muốn lưu thay đổi này?")) return;

    try {
        updateLink(linkId, editForm.slug, editForm.originalUrl);
        setEditingLinkId(null);
        refreshData();
    } catch (error: any) {
        alert(error.message);
    }
  };

  // --- Pagination & Filtering Helpers ---

  // Users
  const totalUserPages = Math.ceil(users.length / USERS_PER_PAGE);
  const paginatedUsers = users.slice(
    (userPage - 1) * USERS_PER_PAGE,
    userPage * USERS_PER_PAGE
  );

  // Links (Filter then Paginate)
  const filteredLinks = links.filter(l => 
    l.slug.toLowerCase().includes(linkSearchTerm.toLowerCase()) || 
    l.originalUrl.toLowerCase().includes(linkSearchTerm.toLowerCase())
  );
  const totalLinkPages = Math.ceil(filteredLinks.length / LINKS_PER_PAGE);
  const paginatedLinks = filteredLinks.slice(
    (linkPage - 1) * LINKS_PER_PAGE,
    linkPage * LINKS_PER_PAGE
  );


  if (currentUser.role !== UserRole.ADMIN) {
    return <div className="p-10 text-center text-red-600">Bạn không có quyền truy cập trang này.</div>;
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <div className="sm:flex sm:items-center">
        <div className="sm:flex-auto">
          <h1 className="text-2xl font-bold text-gray-900">Trang Quản Trị</h1>
          <p className="mt-2 text-sm text-gray-700">Quản lý người dùng và tất cả các link trong hệ thống.</p>
        </div>
      </div>

      <div className="mt-6 border-b border-gray-200">
        <nav className="-mb-px flex space-x-8">
          <button
            onClick={() => setActiveTab('users')}
            className={`${activeTab === 'users' ? 'border-indigo-500 text-indigo-600' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'} whitespace-nowrap py-4 px-1 border-b-2 font-medium text-sm`}
          >
            Người dùng ({users.length})
          </button>
          <button
            onClick={() => setActiveTab('links')}
            className={`${activeTab === 'links' ? 'border-indigo-500 text-indigo-600' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'} whitespace-nowrap py-4 px-1 border-b-2 font-medium text-sm`}
          >
            Tất cả Links ({links.length})
          </button>
        </nav>
      </div>

      <div className="mt-8 flex flex-col">
        {/* Search Bar for Links */}
        {activeTab === 'links' && (
            <div className="mb-4">
                <input 
                    type="text"
                    placeholder="Tìm kiếm theo Slug hoặc URL..."
                    className="shadow-sm focus:ring-indigo-500 focus:border-indigo-500 block w-full sm:text-sm border-gray-300 rounded-md p-2 border"
                    value={linkSearchTerm}
                    onChange={(e) => setLinkSearchTerm(e.target.value)}
                />
            </div>
        )}

        <div className="-my-2 -mx-4 overflow-x-auto sm:-mx-6 lg:-mx-8">
          <div className="inline-block min-w-full py-2 align-middle md:px-6 lg:px-8">
            <div className="overflow-hidden shadow ring-1 ring-black ring-opacity-5 md:rounded-lg">

              {/* USERS TABLE */}
              {activeTab === 'users' && (
                <>
                <table className="min-w-full divide-y divide-gray-300">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-3 py-3.5 text-left text-sm font-semibold text-gray-900">Tên</th>
                      <th className="px-3 py-3.5 text-left text-sm font-semibold text-gray-900">Email</th>
                      <th className="px-3 py-3.5 text-left text-sm font-semibold text-gray-900">Vai trò</th>
                      <th className="relative py-3.5 pl-3 pr-4 sm:pr-6">
                        <span className="sr-only">Actions</span>
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200 bg-white">
                    {paginatedUsers.map((user) => (
                      <tr key={user.id}>
                        <td className="whitespace-nowrap px-3 py-4 text-sm text-gray-900">{user.name}</td>
                        <td className="whitespace-nowrap px-3 py-4 text-sm text-gray-500">{user.email}</td>
                        <td className="whitespace-nowrap px-3 py-4 text-sm text-gray-500">
                          <button 
                            onClick={() => handleRoleChange(user)}
                            className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium cursor-pointer border hover:opacity-80 transition-opacity ${user.role === UserRole.ADMIN ? 'bg-purple-100 text-purple-800 border-purple-200' : 'bg-green-100 text-green-800 border-green-200'}`}
                            title="Nhấn để đổi vai trò"
                          >
                            {user.role} <span className="ml-1 text-[10px] opacity-60">⇄</span>
                          </button>
                        </td>
                        <td className="relative whitespace-nowrap py-4 pl-3 pr-4 text-right text-sm font-medium sm:pr-6">
                          {user.role !== UserRole.ADMIN && (
                            <button onClick={() => handleDeleteUser(user.id)} className="text-red-600 hover:text-red-900">Xóa</button>
                          )}
                        </td>
                      </tr>
                    ))}
                    {paginatedUsers.length === 0 && (
                        <tr><td colSpan={4} className="text-center py-4 text-gray-500">Không có dữ liệu</td></tr>
                    )}
                  </tbody>
                </table>

                {/* User Pagination */}
                {totalUserPages > 1 && (
                    <div className="bg-white px-4 py-3 flex items-center justify-between border-t border-gray-200 sm:px-6">
                        <div className="flex-1 flex justify-between sm:hidden">
                            <button onClick={() => setUserPage(p => Math.max(1, p - 1))} disabled={userPage === 1} className="relative inline-flex items-center px-4 py-2 border border-gray-300 text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 disabled:opacity-50">Trước</button>
                            <button onClick={() => setUserPage(p => Math.min(totalUserPages, p + 1))} disabled={userPage === totalUserPages} className="ml-3 relative inline-flex items-center px-4 py-2 border border-gray-300 text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 disabled:opacity-50">Sau</button>
                        </div>
                        <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
                            <div>
                                <p className="text-sm text-gray-700">
                                    Trang <span className="font-medium">{userPage}</span> / <span className="font-medium">{totalUserPages}</span>
                                </p>
                            </div>
                            <div>
                                <nav className="relative z-0 inline-flex rounded-md shadow-sm -space-x-px" aria-label="Pagination">
                                    <button onClick={() => setUserPage(p => Math.max(1, p - 1))} disabled={userPage === 1} className="relative inline-flex items-center px-2 py-2 rounded-l-md border border-gray-300 bg-white text-sm font-medium text-gray-500 hover:bg-gray-50 disabled:opacity-50">
                                        <span className="sr-only">Trước</span>
                                        &larr;
                                    </button>
                                    <button onClick={() => setUserPage(p => Math.min(totalUserPages, p + 1))} disabled={userPage === totalUserPages} className="relative inline-flex items-center px-2 py-2 rounded-r-md border border-gray-300 bg-white text-sm font-medium text-gray-500 hover:bg-gray-50 disabled:opacity-50">
                                        <span className="sr-only">Sau</span>
                                        &rarr;
                                    </button>
                                </nav>
                            </div>
                        </div>
                    </div>
                )}
                </>
              )}

              {/* LINKS TABLE */}
              {activeTab === 'links' && (
                <>
                <table className="min-w-full divide-y divide-gray-300">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-3 py-3.5 text-left text-sm font-semibold text-gray-900 w-1/6">Slug</th>
                      <th className="px-3 py-3.5 text-left text-sm font-semibold text-gray-900 w-1/3">Original URL</th>
                      <th className="px-3 py-3.5 text-left text-sm font-semibold text-gray-900 w-1/6">Người tạo</th>
                      <th className="px-3 py-3.5 text-left text-sm font-semibold text-gray-900 w-1/12">Clicks</th>
                      <th className="relative py-3.5 pl-3 pr-4 sm:pr-6">
                        <span className="sr-only">Actions</span>
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200 bg-white">
                    {paginatedLinks.map((link) => {
                      const isEditing = editingLinkId === link.id;
                      return (
                      <tr key={link.id}>
                        {isEditing ? (
                            <>
                                <td className="px-3 py-4">
                                    <input 
                                        type="text" 
                                        className="w-full border-gray-300 rounded-md text-sm p-1 border" 
                                        value={editForm.slug}
                                        onChange={e => setEditForm({...editForm, slug: e.target.value})}
                                    />
                                </td>
                                <td className="px-3 py-4">
                                    <input 
                                        type="text" 
                                        className="w-full border-gray-300 rounded-md text-sm p-1 border" 
                                        value={editForm.originalUrl}
                                        onChange={e => setEditForm({...editForm, originalUrl: e.target.value})}
                                    />
                                </td>
                            </>
                        ) : (
                            <>
                                <td className="whitespace-nowrap px-3 py-4 text-sm text-indigo-600 font-medium">{link.slug}</td>
                                <td className="px-3 py-4 text-sm text-gray-500 max-w-xs truncate" title={link.originalUrl}>{link.originalUrl}</td>
                            </>
                        )}

                        <td className="whitespace-nowrap px-3 py-4 text-sm text-gray-500">
                          {link.creatorId === 'guest' ? 'Khách' : (users.find(u => u.id === link.creatorId)?.name || 'Unknown')}
                        </td>
                        <td className="whitespace-nowrap px-3 py-4 text-sm text-gray-500">{link.clicks}</td>
                        <td className="relative whitespace-nowrap py-4 pl-3 pr-4 text-right text-sm font-medium sm:pr-6 space-x-2">
                           {isEditing ? (
                               <>
                                <button onClick={() => saveEditing(link.id)} className="text-green-600 hover:text-green-900 font-medium">Lưu</button>
                                <button onClick={cancelEditing} className="text-gray-500 hover:text-gray-700">Hủy</button>
                               </>
                           ) : (
                               <>
                                <button onClick={() => startEditing(link)} className="text-blue-600 hover:text-blue-900 bg-blue-50 px-2 py-1 rounded">Sửa</button>
                                <button onClick={() => handleSimulateVisit(link.slug)} className="text-indigo-600 hover:text-indigo-900 bg-indigo-50 px-2 py-1 rounded">Visit</button>
                                <button onClick={() => handleDeleteLink(link.id)} className="text-red-600 hover:text-red-900 bg-red-50 px-2 py-1 rounded">Xóa</button>
                               </>
                           )}
                        </td>
                      </tr>
                    )})}
                    {paginatedLinks.length === 0 && (
                        <tr><td colSpan={5} className="text-center py-4 text-gray-500">Không tìm thấy link nào</td></tr>
                    )}
                  </tbody>
                </table>

                {/* Link Pagination */}
                {totalLinkPages > 1 && (
                    <div className="bg-white px-4 py-3 flex items-center justify-between border-t border-gray-200 sm:px-6">
                        <div className="flex-1 flex justify-between sm:hidden">
                            <button onClick={() => setLinkPage(p => Math.max(1, p - 1))} disabled={linkPage === 1} className="relative inline-flex items-center px-4 py-2 border border-gray-300 text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 disabled:opacity-50">Trước</button>
                            <button onClick={() => setLinkPage(p => Math.min(totalLinkPages, p + 1))} disabled={linkPage === totalLinkPages} className="ml-3 relative inline-flex items-center px-4 py-2 border border-gray-300 text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 disabled:opacity-50">Sau</button>
                        </div>
                        <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
                            <div>
                                <p className="text-sm text-gray-700">
                                    Trang <span className="font-medium">{linkPage}</span> / <span className="font-medium">{totalLinkPages}</span>
                                </p>
                            </div>
                            <div>
                                <nav className="relative z-0 inline-flex rounded-md shadow-sm -space-x-px" aria-label="Pagination">
                                    <button onClick={() => setLinkPage(p => Math.max(1, p - 1))} disabled={linkPage === 1} className="relative inline-flex items-center px-2 py-2 rounded-l-md border border-gray-300 bg-white text-sm font-medium text-gray-500 hover:bg-gray-50 disabled:opacity-50">
                                        <span className="sr-only">Trước</span>
                                        &larr;
                                    </button>
                                    <button onClick={() => setLinkPage(p => Math.min(totalLinkPages, p + 1))} disabled={linkPage === totalLinkPages} className="relative inline-flex items-center px-2 py-2 rounded-r-md border border-gray-300 bg-white text-sm font-medium text-gray-500 hover:bg-gray-50 disabled:opacity-50">
                                        <span className="sr-only">Sau</span>
                                        &rarr;
                                    </button>
                                </nav>
                            </div>
                        </div>
                    </div>
                )}
                </>
              )}

            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Admin;

export enum UserRole {
  USER = 'USER',
  ADMIN = 'ADMIN',
  OWNER = 'OWNER'
}

export interface User {
  id: string;
  email: string;
  name: string;
  role: UserRole;
  password?: string; // In a real app, never store plain text
  createdAt: string;
}

export interface DailyStat {
  date: string; // YYYY-MM-DD
  count: number;
}

export interface ShortLink {
  id: string;
  originalUrl: string;
  slug: string;
  creatorId: string; // 'guest' or user.id
  clicks: number;
  createdAt: string;
  lastClickedAt?: string;
  expiresAt?: string | null; // ISO string
  history?: DailyStat[];
}

export interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
}

export interface ClickStat {
  date: string;
  count: number;
}

