  const history: DailyStat[] = [];
  for (let i = days; i >= 0; i--) {
    const d = new Date();
    d.setDate(d.getDate() - i);
    history.push({
      date: d.toISOString().split('T')[0],
      count: Math.floor(Math.random() * 10)
    });
  }
  return history;
};

