import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { getLinkBySlug, incrementClick } from '../services/mockBackend';
import { useLanguage } from '../contexts/LanguageContext';

const RedirectHandler: React.FC = () => {
  const { t } = useLanguage();
  const { slug } = useParams<{ slug: string }>();
  const [status, setStatus] = useState<'checking' | 'redirecting' | 'expired' | 'not-found'>('checking');
  const [targetUrl, setTargetUrl] = useState('');

  useEffect(() => {
    if (!slug) {
        setStatus('not-found');
        return;
    }

    const checkLink = async () => {
      // Simulate network delay
      await new Promise(resolve => setTimeout(resolve, 500));

      const link = getLinkBySlug(slug);

      if (!link) {
        setStatus('not-found');
        return;
      }

      if (link.expiresAt && new Date(link.expiresAt) < new Date()) {
        setStatus('expired');
        return;
      }

      // Record click and redirect
      incrementClick(link.id);
      setTargetUrl(link.originalUrl);
      setStatus('redirecting');

      // Perform redirect
      window.location.href = link.originalUrl;
    };

    checkLink();
  }, [slug]);

  if (status === 'checking' || status === 'redirecting') {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 dark:bg-gray-900 transition-colors duration-200">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mb-4"></div>
        <p className="text-gray-600 dark:text-gray-300 font-medium">
            {status === 'checking' ? t('redirect.checking') : t('redirect.redirecting')}
        </p>
        {status === 'redirecting' && (
            <p className="text-xs text-gray-400 dark:text-gray-500 mt-2">{t('redirect.manual')} <a href={targetUrl} className="text-indigo-600 dark:text-indigo-400 underline">here</a>.</p>
        )}
      </div>
    );
  }

  if (status === 'expired') {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-gray-900 px-4 transition-colors duration-200">
        <div className="max-w-md w-full bg-white dark:bg-gray-800 shadow-lg rounded-lg p-8 text-center border border-gray-100 dark:border-gray-700">
          <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-red-100 dark:bg-red-900/30 mb-6">
            <svg className="h-8 w-8 text-red-600 dark:text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          </div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">{t('redirect.expired.title')}</h2>
          <p className="text-gray-600 dark:text-gray-400 mb-8">
            {t('redirect.expired.desc')}
          </p>
          <div className="flex flex-col space-y-3">
             <Link to="/" className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700">
               {t('redirect.btn.home')}
             </Link>
             <Link to="/login" className="w-full flex justify-center py-2 px-4 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
               {t('nav.login')}
             </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-gray-900 px-4 transition-colors duration-200">
        <div className="text-center">
            <h1 className="text-6xl font-bold text-gray-900 dark:text-white">{t('redirect.404.title')}</h1>
            <p className="text-xl text-gray-600 dark:text-gray-400 mt-4">{t('redirect.404.desc')}</p>
            <div className="mt-8">
                <Link to="/" className="text-indigo-600 dark:text-indigo-400 font-medium hover:text-indigo-500 dark:hover:text-indigo-300">
                    &larr; {t('redirect.btn.home')}
                </Link>
            </div>
        </div>
    </div>
  );
};

export default RedirectHandler;

import React, { useEffect, useState } from 'react';
import QRCode from 'qrcode';
import { useLanguage } from '../contexts/LanguageContext';

interface QRCodeModalProps {
  originalUrl: string;
  slug: string;
  onClose: () => void;
}

const QRCodeModal: React.FC<QRCodeModalProps> = ({ originalUrl, slug, onClose }) => {
  const { t } = useLanguage();
  const [dataUrl, setDataUrl] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const generateCombinedImage = async () => {
      try {
        setLoading(true);
        // 1. Generate the QR Code as a Data URL
        const qrCodeUrl = await QRCode.toDataURL(originalUrl, { 
          width: 200, 
          margin: 1,
          color: {
            dark: '#000000',
            light: '#ffffff'
          }
        });

        // 2. Create a Canvas to combine elements
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Canvas dimensions
        const width = 300;
        const height = 350;
        canvas.width = width;
        canvas.height = height;

        // 3. Draw Background
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, width, height);

        // 4. Draw Website Name (Header)
        ctx.fillStyle = '#4F46E5'; // Indigo-600
        ctx.font = 'bold 24px Inter, sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('ShortAI', width / 2, 40);

        // 5. Draw QR Code Image
        const qrImage = new Image();
        qrImage.src = qrCodeUrl;

        await new Promise((resolve) => {
            qrImage.onload = () => {
                // Center the QR code (200x200)
                ctx.drawImage(qrImage, (width - 200) / 2, 80);
                resolve(true);
            };
        });

        // 6. Draw Footer Label
        ctx.fillStyle = '#6B7280'; // Gray-500
        ctx.font = '12px Inter, sans-serif';
        ctx.fillText(t('modal.qr.scan'), width / 2, 295);

        // 7. Draw Original URL (Footer)
        ctx.fillStyle = '#111827'; // Gray-900
        ctx.font = '13px Inter, sans-serif';

        // Truncate URL if too long
        let displayUrl = originalUrl;
        if (displayUrl.length > 35) {
            displayUrl = displayUrl.substring(0, 32) + '...';
        }
        ctx.fillText(displayUrl, width / 2, 315);

        // 8. Set result
        setDataUrl(canvas.toDataURL('image/png'));
      } catch (error) {
        console.error("Failed to generate QR canvas", error);
      } finally {
        setLoading(false);
      }
    };

    generateCombinedImage();
  }, [originalUrl, t]);

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto" aria-labelledby="modal-title" role="dialog" aria-modal="true">
      <div className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
        <div className="fixed inset-0 bg-gray-500 bg-opacity-75 transition-opacity" onClick={onClose} aria-hidden="true"></div>
        <span className="hidden sm:inline-block sm:align-middle sm:h-screen" aria-hidden="true">&#8203;</span>
        <div className="inline-block align-bottom bg-white dark:bg-gray-800 rounded-lg px-4 pt-5 pb-4 text-left overflow-hidden shadow-xl transform transition-all sm:my-8 sm:align-middle sm:max-w-sm sm:w-full sm:p-6 border border-gray-200 dark:border-gray-700">
          <div className="text-center">
            <h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white" id="modal-title">
              {t('modal.qr.title')} /{slug}
            </h3>
            <div className="mt-4 flex justify-center bg-gray-50 dark:bg-gray-700 p-4 rounded-lg">
              {dataUrl ? (
                <img src={dataUrl} alt="QR Code" className="shadow-sm rounded max-w-full h-auto" />
              ) : (
                <div className="h-64 w-64 flex items-center justify-center bg-gray-100 dark:bg-gray-600 rounded">
                  <div className="animate-spin h-8 w-8 border-b-2 border-indigo-600 dark:border-indigo-400 rounded-full"></div>
                </div>
              )}
            </div>
            <p className="mt-2 text-xs text-gray-500 dark:text-gray-400 px-2">
                {t('modal.qr.desc')}
            </p>
          </div>
          <div className="mt-5 sm:mt-6 grid grid-cols-2 gap-3">
             <button
              type="button"
              className="w-full inline-flex justify-center rounded-md border border-gray-300 dark:border-gray-600 shadow-sm px-4 py-2 bg-white dark:bg-gray-700 text-base font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600 focus:outline-none sm:text-sm"
              onClick={onClose}
            >
              {t('common.close')}
            </button>
            <a
              href={dataUrl}
              download={`ShortAI-${slug}.png`}
              className={`w-full inline-flex justify-center rounded-md border border-transparent shadow-sm px-4 py-2 bg-indigo-600 text-base font-medium text-white hover:bg-indigo-700 focus:outline-none sm:text-sm ${loading ? 'pointer-events-none opacity-50' : ''}`}
            >
              {t('common.download')}
            </a>
          </div>
        </div>
      </div>
    </div>
  );
};

export default QRCodeModal;

import React, { useState } from 'react';
import { bulkCreateShortLinks } from '../services/mockBackend';
import { useLanguage } from '../contexts/LanguageContext';

interface BulkCreateModalProps {
  userId: string;
  onSuccess: () => void;
  onClose: () => void;
}

const BulkCreateModal: React.FC<BulkCreateModalProps> = ({ userId, onSuccess, onClose }) => {
  const { t } = useLanguage();
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{success: number, errors: string[]} | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setFile(e.target.files[0]);
      setResult(null);
    }
  };

  const handleUpload = async () => {
    if (!file) return;
    setLoading(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      if (!text) {
        setLoading(false);
        return;
      }

      // Simple CSV Parse: url,slug (optional)
      const lines = text.split(/\r?\n/);
      const items: { url: string; slug?: string }[] = [];

      for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed) continue;
        const [url, slug] = trimmed.split(',').map(s => s.trim());
        if (url) {
            // Basic URL validation could go here
            items.push({ url, slug });
        }
      }

      if (items.length === 0) {
         setLoading(false);
         alert("File trống hoặc không đúng định dạng.");
         return;
      }

      const res = await bulkCreateShortLinks(items, userId);
      setResult(res);
      setLoading(false);
      if (res.success > 0) onSuccess();
    };

    reader.readAsText(file);
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto" aria-labelledby="modal-title" role="dialog" aria-modal="true">
      <div className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
        <div className="fixed inset-0 bg-gray-500 bg-opacity-75 transition-opacity" onClick={onClose} aria-hidden="true"></div>
        <span className="hidden sm:inline-block sm:align-middle sm:h-screen" aria-hidden="true">&#8203;</span>
        <div className="inline-block align-bottom bg-white dark:bg-gray-800 rounded-lg px-4 pt-5 pb-4 text-left overflow-hidden shadow-xl transform transition-all sm:my-8 sm:align-middle sm:max-w-lg sm:w-full sm:p-6 border border-gray-200 dark:border-gray-700">
          <div className="sm:flex sm:items-start">
            <div className="mx-auto flex-shrink-0 flex items-center justify-center h-12 w-12 rounded-full bg-indigo-100 dark:bg-indigo-900/50 sm:mx-0 sm:h-10 sm:w-10">
              <svg className="h-6 w-6 text-indigo-600 dark:text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
              </svg>
            </div>
            <div className="mt-3 text-center sm:mt-0 sm:ml-4 sm:text-left w-full">
              <h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white" id="modal-title">
                {t('modal.bulk.title')}
              </h3>
              <div className="mt-2">
                <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
                  {t('modal.bulk.desc')} <code>URL, Slug(optional)</code>
                </p>

                {!result ? (
                   <div className="mt-1 flex justify-center px-6 pt-5 pb-6 border-2 border-gray-300 dark:border-gray-600 border-dashed rounded-md hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                    <div className="space-y-1 text-center">
                      <div className="text-sm text-gray-600 dark:text-gray-400">
                        <label htmlFor="file-upload" className="relative cursor-pointer bg-white dark:bg-gray-700 rounded-md font-medium text-indigo-600 dark:text-indigo-400 hover:text-indigo-500 dark:hover:text-indigo-300 focus-within:outline-none">
                          <span className="px-2">{t('modal.bulk.select')}</span>
                          <input id="file-upload" name="file-upload" type="file" accept=".csv" className="sr-only" onChange={handleFileChange} />
                        </label>
                      </div>
                      <p className="text-xs text-gray-500 dark:text-gray-400">
                        {file ? file.name : t('modal.bulk.no_file')}
                      </p>
                    </div>
                  </div>
                ) : (
                  <div className="rounded-md bg-gray-50 dark:bg-gray-700 p-4">
                    <div className="flex">
                      <div className="ml-3">
                        <h3 className="text-sm font-medium text-gray-800 dark:text-white">{t('modal.bulk.result')}</h3>
                        <div className="mt-2 text-sm text-gray-700 dark:text-gray-300">
                          <p className="text-green-600 dark:text-green-400">✓ {t('modal.bulk.success')} {result.success}</p>
                          {result.errors.length > 0 && (
                            <div className="mt-2">
                                <p className="text-red-600 dark:text-red-400 font-medium">⚠ {t('modal.bulk.error')} ({result.errors.length}):</p>
                                <ul className="list-disc list-inside text-red-500 dark:text-red-300 text-xs mt-1 max-h-32 overflow-y-auto">
                                    {result.errors.map((e, i) => <li key={i}>{e}</li>)}
                                </ul>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
          <div className="mt-5 sm:mt-4 sm:flex sm:flex-row-reverse">
            {!result ? (
                <button
                    type="button"
                    disabled={!file || loading}
                    onClick={handleUpload}
                    className="w-full inline-flex justify-center rounded-md border border-transparent shadow-sm px-4 py-2 bg-indigo-600 text-base font-medium text-white hover:bg-indigo-700 focus:outline-none disabled:opacity-50 sm:ml-3 sm:w-auto sm:text-sm"
                >
                    {loading ? t('common.processing') : t('modal.bulk.btn.upload')}
