                          ) : (
                              <>
                                {canEditUser(user) && (
                                    <button onClick={() => startEditingUser(user)} className="text-blue-600 hover:text-blue-900 dark:text-blue-400 dark:hover:text-blue-300 bg-blue-50 dark:bg-blue-900/30 px-2 py-1 rounded">{t('common.edit')}</button>
